begin;
create table if not exists operational_failures(id text primary key,workspace_id text not null references workspaces(id) on delete cascade,brand_id text not null references brands(id) on delete cascade,workflow_id text not null,stage text not null check(stage in('brand-setup','hunter','research','generation','critic','publishing','metrics')),diagnostic_code text not null,summary text not null,retry_disposition text not null check(retry_disposition in('safe','manual-review','blocked')),attempt integer not null check(attempt>0),max_attempts integer not null check(max_attempts>0 and attempt<=max_attempts),state text not null default 'failed' check(state='failed'),trace_id text null,occurred_at timestamptz not null);
create index if not exists ix_operational_failures_brand_time on operational_failures(brand_id,occurred_at desc,id);
create table if not exists retry_requests(id text primary key,workspace_id text not null references workspaces(id) on delete cascade,brand_id text not null references brands(id) on delete cascade,workflow_id text not null,failure_id text not null references operational_failures(id) on delete cascade,attempt integer not null check(attempt>0),idempotency_key text not null,requested_by_account_id text not null references accounts(id) on delete restrict,requested_at timestamptz not null,constraint uq_retry_request_idempotency unique(failure_id,idempotency_key));
create table if not exists automation_controls(id text primary key,workspace_id text not null references workspaces(id) on delete cascade,brand_id text not null references brands(id) on delete cascade,automation_key text not null,stage text not null check(stage in('brand-setup','hunter','research','generation','critic','publishing','metrics')),status text not null check(status in('enabled','disabled')),version integer not null check(version>0),created_at timestamptz not null,disabled_at timestamptz null,disabled_by_account_id text null references accounts(id) on delete restrict,disabled_reason text null,constraint uq_automation_control_brand_key unique(brand_id,automation_key));
create table if not exists workflow_budgets(id text primary key,workspace_id text not null references workspaces(id) on delete cascade,brand_id text not null references brands(id) on delete cascade,workflow_id text not null,currency text not null check(currency ~ '^[A-Z]{3}$'),limit_micros bigint not null check(limit_micros>0),spent_micros bigint not null default 0 check(spent_micros>=0),version integer not null default 1 check(version>0),created_at timestamptz not null,constraint uq_workflow_budget_scope unique(brand_id,workflow_id,currency),constraint ck_workflow_budget_limit check(spent_micros<=limit_micros));
create table if not exists workflow_cost_events(id text primary key,workspace_id text not null references workspaces(id) on delete cascade,brand_id text not null references brands(id) on delete cascade,workflow_id text not null,kind text not null check(kind in('model','search','tool','social')),provider text not null,currency text not null check(currency ~ '^[A-Z]{3}$'),cost_micros bigint not null check(cost_micros>=0),occurred_at timestamptz not null);
create index if not exists ix_workflow_cost_events_brand_time on workflow_cost_events(brand_id,occurred_at desc,id);
create table if not exists operator_interventions(id text primary key,workspace_id text not null references workspaces(id) on delete cascade,brand_id text not null references brands(id) on delete cascade,actor_account_id text not null references accounts(id) on delete restrict,action text not null check(action in('retry-requested','automation-disabled','content-withdrawn','configuration-corrected','safety-reviewed')),target_type text not null,target_id text not null,reason text not null,related_failure_id text null references operational_failures(id) on delete set null,occurred_at timestamptz not null);
create index if not exists ix_operator_interventions_brand_time on operator_interventions(brand_id,occurred_at desc,id);
commit;
